/* Generated by safe ES module refactor from the existing js/main.js implementation. */

import {
  ADMIN_HOME_PAGE_NAME,
  ADMIN_LOGIN_PAGE_NAME,
  USER_HOME_PAGE_NAME,
  USER_LOGIN_PAGE_NAME
} from "./config.js";

export const USER_LOGIN_PAGE = resolvePagePath(USER_LOGIN_PAGE_NAME);
export const ADMIN_LOGIN_PAGE = resolvePagePath(ADMIN_LOGIN_PAGE_NAME);
export const USER_HOME_PAGE = resolvePagePath(USER_HOME_PAGE_NAME);
export const ADMIN_HOME_PAGE = resolvePagePath(ADMIN_HOME_PAGE_NAME);

export function getCurrentPageName() {
  let filename = String(window.location.pathname || "").split("/").pop().toLowerCase();
  filename = filename.split("?")[0].split("#")[0];

  if (!filename || filename === "" || filename === "index.html" || filename === "index") return "index.html";
  if (filename.includes("ulogin")) return "Ulogin.html";
  if (filename.includes("alogin")) return "Alogin.html";
  if (filename.includes("udash")) return "Udash.html";
  if (filename.includes("adash")) return "Adash.html";
  if (filename.includes("ownerdb")) return "OwnerDB.html";
  if (filename.includes("generatekey")) return "generateKey.html";
  if (filename.includes("checkout")) return "checkout.html";
  if (filename.includes("freepanel")) return "freepanel.html";
  if (filename.includes("change")) return "change.html";
  if (filename.includes("status")) return "status.html";

  return "index.html";
}

export function isPagesContext() {
  return /\/pages\//i.test(String(window.location.pathname || "").replace(/\\/g, "/"));
}

export function resolvePagePath(pageName) {
  const normalizedPage = String(pageName || "index.html")
    .replace(/^\.\/+/, "")
    .replace(/^pages\//i, "");

  if (normalizedPage.toLowerCase() === "index.html") {
    return isPagesContext() ? "../index.html" : "index.html";
  }

  return isPagesContext() ? normalizedPage : `pages/${normalizedPage}`;
}

export function removePageGuardStyle() {
  const styleEl = document.getElementById("page-guard-style");
  if (styleEl) styleEl.remove();
}

export function revealProtectedBody() {
  removePageGuardStyle();

  if (!document.body) return;

  document.body.style.display = "";

  document.body.style.opacity = "0";
  document.body.style.transform = "translateY(4px)";
  document.body.style.transition = "opacity 0.24s ease, transform 0.24s ease";

  requestAnimationFrame(() => {
    document.body.style.opacity = "1";
    document.body.style.transform = "translateY(0)";
  }, 50);
}

export function redirectForRole(role) {
  if (role === "Admin") {
    window.location.replace(ADMIN_HOME_PAGE);
    return;
  }

  if (role === "User") {
    window.location.replace(USER_HOME_PAGE);
    return;
  }

  window.location.replace(resolvePagePath("index.html"));
}

export function goTo(page, delayMs = 700) {
  const targetPath = resolvePagePath(page);
  window.setTimeout(() => {
    window.location.href = targetPath;
  }, delayMs);
}
